// LC 3。不变量：s[left, right] 内每个字符最多出现一次。
// 换题时只改 while 的非法条件：种类数超限见「至多 k 种」模板；若要区间本身，额外记 bestLeft。
static int lengthOfLongestSubstring(String s) {
    int[] freq = new int[128];
    int left = 0;
    int best = 0;
    for (int right = 0; right < s.length(); right++) {
        char in = s.charAt(right);
        freq[in]++;
        // 只把左端推到“刚进来的这个字符”重新唯一，不必把别的字符也清掉
        while (freq[in] > 1) {
            freq[s.charAt(left)]--;
            left++;
        }
        best = Math.max(best, right - left + 1); // 窗口已经合法，最长在这里更新
    }
    return best;
}

// LC 76。不变量：formed == needKinds 时，窗口已覆盖 t 里每种字符的需要次数。
// 换 209：删掉 need/formed，改记 sum，sum >= target 时更新长度并 sum -= nums[left++]。
// 209 必须是正数组与正 target；原题 n<=100000、每项<=10000，sum 可用 int；任意正 int 数组改用 long。
// 换覆盖变种：计数下标从 char 改成题目的元素键，入窗/出窗仍要成对加减。
static String minWindow(String s, String t) {
    if (t.isEmpty() || s.length() < t.length()) {
        return "";
    }
    int[] need = new int[128];
    int needKinds = 0;
    for (int i = 0; i < t.length(); i++) {
        if (need[t.charAt(i)]++ == 0) {
            needKinds++;
        }
    }
    int[] window = new int[128];
    int formed = 0;
    int left = 0;
    int bestLen = Integer.MAX_VALUE;
    int bestLeft = 0;
    for (int right = 0; right < s.length(); right++) {
        char in = s.charAt(right);
        window[in]++;
        // 次数刚好凑齐才 +1；超出 need 或 t 里根本没有的字符都不计
        if (need[in] > 0 && window[in] == need[in]) {
            formed++;
        }
        while (formed == needKinds) { // 仍然覆盖：先记答案，再尝试丢左端
            if (right - left + 1 < bestLen) {
                bestLen = right - left + 1;
                bestLeft = left;
            }
            char out = s.charAt(left++);
            window[out]--;
            if (need[out] > 0 && window[out] < need[out]) {
                formed--;
            }
        }
    }
    return bestLen == Integer.MAX_VALUE ? "" : s.substring(bestLeft, bestLeft + bestLen);
}

// LC 438，输入仅小写字母。窗口长度恒为 p.length()，合法条件是 26 槽与 p 完全相等。
// 换 567：equals 成立立刻 return true，扫完 return false。
// 扩展到含大写、数字或标点的 ASCII 输入时才可用 int[128]，按字符值索引，不减 'a'。
// 非 ASCII 输入不能直接用 128 槽；先约定字符单位。若按 Unicode 码点计数，需按码点遍历、用 Map<Integer,Integer> 等结构，并另维护原字符串索引。
static java.util.List<Integer> findAnagrams(String s, String p) {
    java.util.List<Integer> ans = new java.util.ArrayList<>();
    int n = s.length();
    int m = p.length();
    if (m == 0 || n < m) {
        return ans;
    }
    int[] need = new int[26];
    int[] window = new int[26];
    for (int i = 0; i < m; i++) {
        need[p.charAt(i) - 'a']++;
    }
    for (int i = 0; i < n; i++) {
        window[s.charAt(i) - 'a']++;
        if (i >= m) {
            window[s.charAt(i - m) - 'a']--; // 右端进来一个，左端必须出去一个
        }
        if (i >= m - 1 && java.util.Arrays.equals(window, need)) {
            ans.add(i - m + 1);
        }
    }
    return ans;
}

// LC 340。不变量：窗口内不同字符数 <= k。超标才收缩，收缩后更新最大长度。
// 换 904：k 固定为 2。水果种类不是 ASCII 时，freq 改成 Map<Integer,Integer>：
// 计数从 0 变为 1 时 distinct++，减到 0 时 distinct--，其余与下面相同。
static int lengthOfLongestKDistinct(String s, int k) {
    if (k <= 0 || s.isEmpty()) {
        return 0;
    }
    int[] freq = new int[128];
    int distinct = 0;
    int left = 0;
    int best = 0;
    for (int right = 0; right < s.length(); right++) {
        char in = s.charAt(right);
        if (freq[in] == 0) {
            distinct++;
        }
        freq[in]++;
        while (distinct > k) {
            char out = s.charAt(left++);
            freq[out]--;
            if (freq[out] == 0) {
                distinct--;
            }
        }
        best = Math.max(best, right - left + 1);
    }
    return best;
}

lc-face-extra-8.code:
// 本入口合同：k≥0，种类、窗口长度和下标均以 Java UTF-16 char 代码单元计，不是 Unicode 码点。null、空串或 k=0 返回0；k<0 不在调用域内，入口不检查负 k。
import java.util.HashMap;
import java.util.Map;

class Solution {
    public int lengthOfLongestSubstringKDistinct(String s, int k) {
        if (s == null || s.length() == 0 || k == 0) {
            return 0;
        }
        Map<Character, Integer> cnt = new HashMap<>();
        int left = 0, ans = 0;
        for (int right = 0; right < s.length(); right++) {
            char c = s.charAt(right);
            cnt.put(c, cnt.getOrDefault(c, 0) + 1);
            // 种类超过 k 就缩左端，频次归零则删键
            while (cnt.size() > k) {
                char lc = s.charAt(left);
                cnt.put(lc, cnt.get(lc) - 1);
                if (cnt.get(lc) == 0) {
                    cnt.remove(lc);
                }
                left++;
            }
            ans = Math.max(ans, right - left + 1);
        }
        return ans;
    }
}

lc-face-extra-7.code:
// LC567 原题：s1、s2 均非 null，长度各为1..10000，只含小写英文字母 a-z。26项计数以此为前提；空模式、其他字符或 null 的行为不属于此接口合同。
class Solution {
    public boolean checkInclusion(String s1, String s2) {
        if (s2.length() < s1.length()) {
            return false;
        }
        int[] cnt = new int[26];
        for (char c : s1.toCharArray()) {
            cnt[c - 'a']++;
        }
        // need 表示还差多少个 s1 中的字符
        int left = 0, need = s1.length();
        for (int right = 0; right < s2.length(); right++) {
            if (cnt[s2.charAt(right) - 'a']-- > 0) {
                need--;
            }
            // 窗口超长就弹出左端，并把多减的计数加回
            if (right - left + 1 > s1.length()) {
                if (++cnt[s2.charAt(left++) - 'a'] > 0) {
                    need++;
                }
            }
            if (need == 0) {
                return true;
            }
        }
        return false;
    }
}

76.code:
// LC76 原题：s、t 均非 null，长度各为1..100000，只含大小写英文字母。因字符都在 ASCII 内，主实现的128项数组下标合法；专题中的 ACM 实现也沿用非空目标。主入口额外在空 t 时返回空串，不代表所有专题模板具有同一扩展行为。
import java.util.*; // Java 常用集合、队列、堆与数组工具

class Solution {
    public String minWindow(String s, String t) {
        if (t.isEmpty() || s.length() < t.length()) return "";

        // need[c] 表示当前窗口还欠多少个 c，用来判断是否补上了真实需求。
        int[] need = new int[128];
        for (char c : t.toCharArray()) need[c]++;

        int missing = t.length();
        int left = 0;
        int bestStart = 0;
        int bestLength = Integer.MAX_VALUE;

        for (int right = 0; right < s.length(); right++) {
            char incoming = s.charAt(right);

            // 原来还欠这个字符时，吃进它才算补上一个需求。
            if (need[incoming] > 0) missing--;
            need[incoming]--;

            // 已覆盖 t 后尽量右移左边界，才能得到更短的合法窗口。
            while (missing == 0) {
                int length = right - left + 1;
                if (length < bestLength) {
                    bestLength = length;
                    bestStart = left;
                }

                char outgoing = s.charAt(left++);
                need[outgoing]++;

                // 归还后重新变成正数，说明移走的是必需字符，窗口不再合法。
                if (need[outgoing] > 0) missing++;
            }
        }

        return bestLength == Integer.MAX_VALUE
                ? ""
                : s.substring(bestStart, bestStart + bestLength);
    }
}

