// Try 阶段：预留资源
public boolean tryDeductStock(String orderId, int count) {
    // 冻结库存（不实际扣减）
    int rows = jdbc.update(
        "UPDATE products SET frozen = frozen + ? WHERE id = 1 AND stock - frozen >= ?",
        count, count);
    return rows > 0;
}

// Confirm 阶段：真正扣减
public boolean confirmDeductStock(String orderId, int count) {
    int rows = jdbc.update(
        "UPDATE products SET stock = stock - ?, frozen = frozen - ? WHERE id = 1",
        count, count);
    return rows > 0;
}

// Cancel 阶段：释放冻结
public boolean cancelDeductStock(String orderId, int count) {
    int rows = jdbc.update(
        "UPDATE products SET frozen = frozen - ? WHERE id = 1", count);
    return rows > 0;
}

// 按 user_id 分 16 个库，每库 16 张表（共 256 张表）
public class ShardingRouter {
    private static final int DB_COUNT = 16;
    private static final int TABLE_COUNT_PER_DB = 16;

    public String routeDb(long userId) {
        if (userId <= 0) throw new IllegalArgumentException("positive userId");
        int dbIndex = (int) (userId % DB_COUNT);
        return "db_" + dbIndex;
    }

    public String routeTable(long userId) {
        if (userId <= 0) throw new IllegalArgumentException("positive userId");
        int tableIndex = (int) ((userId / DB_COUNT) % TABLE_COUNT_PER_DB);
        return "orders_" + tableIndex;
    }
}

// 下列是依赖注入伪代码；Order/router/jdbcFor/queryShard 未提供，不能作为完整 Java 编译。
// jdbcFor(db)须在白名单db_0..db_15中选对应DataSource/JDBC客户端；表名也只由router生成。
// 查询：单分片查询，必须按 db 选择 DataSource，不能算出 db 后忽略它
public Order getOrder(long userId, long orderId) {
    String db = router.routeDb(userId);
    String table = router.routeTable(userId);
    return jdbcFor(db).query("SELECT * FROM " + table + " WHERE user_id=? AND order_id=?",
        userId, orderId);
}

// 跨分片查询：广播 + 归并
public List<Order> getOrdersByTime(LocalDate date) {
    List<Order> results = new ArrayList<>();
    for (int db = 0; db < DB_COUNT; db++) {
        for (int table = 0; table < TABLE_COUNT_PER_DB; table++) {
            results.addAll(queryShard(db, table, date));
        }
    }
    return results;
}

